'use strict';

/*
 * Generates the consolidated runtime bundle owners declared by data/runtime-manifest.js.
 *
 * A bundle is a pure ordered concatenation of the historical fragments in one
 * ownership area. Nothing is minified, reordered, wrapped, or rewritten, so the
 * consolidated owner executes exactly the code the historical chain executed, in
 * exactly the frozen v9.5 order. The historical fragments stay on disk as the
 * regression ledger; the browser simply stops making one request per fragment.
 */

const crypto=require('crypto');
const fs=require('fs');
const path=require('path');

const root=path.join(__dirname,'..');
const manifest=require(path.join(root,'data','runtime-manifest.js'));

const read=rel=>fs.readFileSync(path.join(root,rel),'utf8').replace(/\r\n/g,'\n');
const hash=list=>crypto.createHash('sha256').update(list.join('\n')).digest('hex');

function areas(){
 const list=manifest.bundles&&manifest.bundles.areas;
 if(!Array.isArray(list)||!list.length)throw new Error('runtime manifest bundles.areas is required');
 return list;
}

/*
 * The separator is load-bearing. Two historical fragments concatenated without an
 * explicit terminator can change meaning through automatic semicolon insertion —
 * a fragment ending in `foo()` followed by one starting with `(function(){…})()`
 * would parse as a single call expression. The empty statement prevents that.
 */
function segment(rel){
 const body=read(rel).replace(/\s+$/,'');
 if(/^\s*(['"])use strict\1\s*;/.test(body))throw new Error('fragment declares a strict-mode prologue that would leak across the bundle: '+rel);
 return '/* obol-runtime-fragment: '+rel+' */\n'+body+manifest.bundles.separator;
}

function expected(area){
 if(!area.fragments.length)throw new Error('bundle area declares no fragments: '+area.id);
 for(const rel of area.fragments){
  if(!/^(assets|data)\/[^/]+\.js$/.test(rel))throw new Error('bundle fragment must stay inside assets/ or data/: '+rel);
  if(manifest.bundles.owners.includes(rel))throw new Error('bundle owner cannot be its own fragment: '+rel);
 }
 return [
  '/*',
  ' * Generated by tools/sync-runtime-bundles.js from data/runtime-manifest.js.',
  ' * Do not edit manually.',
  ' *',
  ' * Ownership area: '+area.id+' ('+area.scope+') — '+area.label,
  ' * '+area.description,
  ' *',
  ' * This file is the single current runtime owner for '+area.fragments.length+' historical',
  ' * fragments. It is their exact ordered concatenation, so observable behavior and',
  ' * global load order are unchanged; only the request count differs. The fragments',
  ' * remain on disk as the frozen regression ledger.',
  ' *',
  ' * Fragment order sha256: '+hash(area.fragments),
  ' * First fragment: '+area.fragments[0],
  ' * Last fragment:  '+area.fragments[area.fragments.length-1],
  ' */',
  ''
 ].join('\n')+area.fragments.map(segment).join('');
}

function main(){
 const write=process.argv.includes('--write');
 let stale=0,written=0,fragments=0;
 for(const area of areas()){
  const target=path.join(root,area.owner);
  const next=expected(area);
  const current=fs.existsSync(target)?fs.readFileSync(target,'utf8').replace(/\r\n/g,'\n'):'';
  fragments+=area.fragments.length;
  if(write){
   if(current!==next){fs.writeFileSync(target,next);written++;}
  }else if(current!==next){
   console.error(area.owner+' is out of sync with its '+area.fragments.length+' manifest fragments.');
   stale++;
  }
 }

 if(write){
  console.log('Runtime bundles synchronized: '+areas().length+' ownership areas own '+fragments+' historical fragments ('+written+' rewritten).');
 }else if(stale){
  console.error('Run node tools/sync-runtime-bundles.js --write');
  process.exit(1);
 }else{
  console.log('Runtime bundles match the manifest: '+areas().length+' ownership areas own '+fragments+' historical fragments.');
 }
}

if(require.main===module)main();

module.exports={areas,expected,segment,main};
